/// tanh(x) = 1 - 2 / (2^(2x log2 e) + 1), with round_exp2_6_full. Saturates through inf;
/// cancels near 0 (absolute error ~ulp(1)).
template<typename T>
inline auto exp2_tanh(T x) -> T
{
    const auto t = std::clamp(x * T(2.8853900817779268), T(-151), T(128));
    const auto e = round_exp2_6_full<T>(t);
    return T(1) - T(2) / (e + T(1));
}

/// tanh(x) = (e - 1) / (e - 1 + 2), e - 1 = 2^n f Q(f) + (2^n - 1), 2x log2 e = n + f.
/// The -1 stays exact, so small x keeps relative precision. x clamped to ±9.1.
template<typename T>
inline auto expm1_tanh(T x) -> T
{
    x = std::clamp(x, T(-9.1), T(9.1));
    const auto t = x * T(2.8853900817779268);
    const auto r = std::nearbyint(t);
    const auto f = t - r;
    auto q = T(0.00015461447459864117);
    q = q * f + T(0.0013390867351159438);
    q = q * f + T(0.00961805666989564);
    q = q * f + T(0.055503571042534054);
    q = q * f + T(0.24022650922342687);
    q = q * f + T(0.6931471880293425);
    const auto p = pow2i<T>(static_cast<ieee_int<T>>(r));
    const auto em1 = p * (f * q) + (p - T(1));
    return em1 / (em1 + T(2));
}

